import { resolveSubject } from '@projexlight/sdk-projection';
const subject = await resolveSubject({
  person_id: req.auth.sub,
  app_id: req.auth.app_id,
  tenant_id: req.auth.tenant_id,
});
if (!subject) throw new Error('subject not projected yet; reject + enqueue');

import { enqueueRefresh } from '@projexlight/sdk-projection';
for (const person_id of affectedPeople) {
  await enqueueRefresh({ person_id, app_id, tenant_id });
}

// Driven by the projector worker. To observe:
// subscribeEvents('projection.subject.stale.v1', async (e) => {
//   await page('projection-stale', e.payload);
// });

import { startProjector } from '@projexlight/sdk-projection';
const worker = startProjector({
  bulkRebuild: { tenant_id, force: true },
});
await worker.completed; // resolves when the bulk pass is done
await worker.stop();

import { inboxEnqueue } from '@projexlight/sdk-projection';
// after registerPerson():
await inboxEnqueue({
  kind: 'identity.person.registered',
  payload: { person_id, home_region },
});
